/* ==========================================================================
   PROFESSORS — 05_Data_IO/01_Save_Button.js
   The recursive save: "Save & Download" (and Ctrl/Cmd+S) emits a fresh,
   standalone Professor.html with the entire library embedded in its data
   vault — the same file format as the original proff.html, which can save
   itself again anywhere.

   The pristine proff.html is embedded below as PROFF_TEMPLATE with an
   __APP_DATA_JSON__ placeholder; at save time the placeholder is replaced
   with the live state JSON and the current sort/status selections are
   persisted into the markup (mirroring proff.html's in-DOM behavior).
   Extracted from proff.html lines 2832-2883.
   ==========================================================================
*/

import { state, ui, persist } from '../00_State.js';
import { $, saveBlob, toast } from '../01_Utils.js';
import { closeAllModals } from '../04_Modals/01_Modal_Core.js';
import { clearDragState } from '../03_Professor_List/02_List_Actions.js';
import { setPendingAttachment } from '../04_Modals/03_Paper_Modal.js';
import { render } from '../Professors.js';

export var SAVE_NAME = 'proff.html';

/* ---------- resets transient UI before a save (verbatim from proff.html) ---------- */
export function clearTransientDom() {
  $('#profList').innerHTML = '';
  $('#statsBar').innerHTML = '';
  closeAllModals();
  $('#searchInput').value = '';
  ui.search = '';
  ui.statusFilter = 'all';
  ui.tagFilter = null;
  ui.collapsed = {};
  ui.kbIdx = -1;
  ui.heatYear = null;
  ui.favOnly = false;
  var favB = $('#favBtn');
  if (favB) { favB.classList.remove('active'); favB.setAttribute('aria-pressed', 'false'); }
  var stSel = $('#statusSelect');
  if (stSel) stSel.value = 'all';
  var tb = $('#tagBar');
  tb.hidden = true;
  tb.innerHTML = '';
  $('#scrollTopBtn').hidden = true;
  setPendingAttachment(null);
  clearDragState();
  var hs = $('#heatSection');
  hs.hidden = true;
  hs.innerHTML = '';
  var rs = $('#resumeSection');
  rs.hidden = true;
  rs.innerHTML = '';
  var t = $('#toast');
  t.classList.remove('show');
  $('#toastMsg').textContent = '';
}

/* moves the `selected` attribute onto the current option of a <select> block
   inside the template (the original mutates the live DOM instead) */
function persistSelection(html, selId, value) {
  var re = new RegExp('(<select id="' + selId + '"[\\s\\S]*?</select>)');
  var m = html.match(re);
  if (!m) return html;
  var blk = m[1].replace(/ selected/g, '');
  blk = blk.replace(new RegExp('<option value="' + value + '"'), '<option value="' + value + '" selected');
  return html.replace(re, function () { return blk; });
}

export function buildSaveHtml() {
  clearTransientDom();
  persist();
  var dataJson = '\n' + JSON.stringify(state, null, 2).replace(/</g, '\\u003c') + '\n';
  var html = PROFF_TEMPLATE.replace('__APP_DATA_JSON__', function () { return dataJson; });
  /* carry current sort / status filter into the saved copy (original does this in-DOM) */
  html = persistSelection(html, 'sortSelect', ui.sort);
  html = persistSelection(html, 'statusSelect', ui.statusFilter);
  return html;
}

export function downloadWebsite() {
  persist();
  var html = buildSaveHtml();
  saveBlob(new Blob([html], { type: 'text/html;charset=utf-8' }), SAVE_NAME);
  render();
  toast('Website downloaded — open proff.html anytime; your library is inside it, and it can save itself again.');
}

export function InitSaveButton() {
  $('#saveBtn').addEventListener('click', downloadWebsite);
}

